#include <cstddef>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <string_view>
#include <vector>

void move_zeros(std::span<int> v) {
  std::ptrdiff_t write = 0;  // the next slot for an element that stays
  for (std::ptrdiff_t read = 0; read < std::ssize(v); ++read)
    if (v[read] != 0) v[write++] = v[read];
  for (; write < std::ssize(v); ++write) v[write] = 0;
}

[[nodiscard]] std::string show(std::span<const int> v) {
  std::string out = "{";
  for (std::string_view separator; const int x : v) {
    out += std::format("{}{}", separator, x);
    separator = ", ";
  }
  return out + "}";
}

int main() {
  std::vector<std::vector<int>> cases{{0, 1, 0, 3, 12}, {}, {0, 0}, {5, 6}};
  for (std::vector<int>& v : cases) {
    move_zeros(v);
    std::cout << show(v) << '\n';
  }
}

