#include <algorithm>
#include <format>
#include <iostream>
#include <iterator>
#include <span>
#include <string>
#include <string_view>
#include <vector>

void move_zeros(std::span<int> v) {
  const auto tail = std::ranges::remove(v, 0);  // the kept elements move to the front
  std::ranges::fill(tail, 0);                   // tail is what they left behind
}

[[nodiscard]] std::string show(std::span<const int> v) {
  std::string out = "{";
  for (std::string_view separator; const int x : v) {
    out += std::format("{}{}", separator, x);
    separator = ", ";
  }
  return out + "}";
}

int main() {
  std::vector<int> v{0, 1, 0, 3, 12};
  const auto tail = std::ranges::remove(v, 0);
  std::cout << std::format("remove kept {} elements and left a tail of {}\n", tail.begin() - v.begin(), std::ssize(tail));
  std::vector<int> w{0, 1, 0, 3, 12};
  move_zeros(w);
  std::cout << show(w) << '\n';
}

