[[nodiscard]] std::optional<int> second_largest(std::span<const int> v) {
  std::optional<int> first;
  std::optional<int> second;
  for (const int x : v) {
    if (!first || x > *first) {
      second = first;
      first = x;
    } else if (x != *first && (!second || x > *second)) {
      second = x;
    }
  }
  return second;
}

int main() {
  constexpr int lowest = std::numeric_limits<int>::min();
  const std::vector<std::vector<int>> cases{{3, 5, 5, 4}, {7, 7}, {}, {-1, -3}, {lowest, 0}};
  for (const std::vector<int>& v : cases) {
    const std::optional<int> result = second_largest(v);
    std::cout << (result ? std::to_string(*result) : "no value") << '\n';
  }
}

#include <cstddef>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <string_view>
#include <vector>

std::ptrdiff_t remove_value(std::vector<int>& v, int value) {
  std::ptrdiff_t write = 0;
  for (std::ptrdiff_t read = 0; read < std::ssize(v); ++read)
    if (v[read] != value) v[write++] = v[read];
  const std::ptrdiff_t removed = std::ssize(v) - write;
  v.erase(v.begin() + write, v.end());
  return removed;
}

[[nodiscard]] std::string show(std::span<const int> v) {
  std::string out = "{";
  for (std::string_view separator; const int x : v) {
    out += std::format("{}{}", separator, x);
    separator = ", ";
  }
  return out + "}";
}

int main() {
  std::vector<int> by_hand{3, 2, 2, 3, 4};
  std::vector<int> by_library = by_hand;
  std::vector<int> empty;
  const std::ptrdiff_t removed = remove_value(by_hand, 3);
  const auto erased = std::erase(by_library, 3);  // C++20
  std::cout << std::format("removed {} and {}: {} {}\n", removed, erased, show(by_hand), show(by_library));
  std::cout << std::format("empty: removed {}, {}\n", remove_value(empty, 3), show(empty));
}

#include <array>
#include <cstdint>
#include <format>
#include <iostream>
#include <string_view>

[[nodiscard]] bool is_anagram(std::string_view a, std::string_view b) {
  if (a.size() != b.size()) return false;
  std::array<std::int64_t, 256> counts{};
  const auto slot = [](char c) { return static_cast<unsigned char>(c); };  // char may be negative
  for (const char c : a) ++counts[slot(c)];
  for (const char c : b)
    if (--counts[slot(c)] < 0) return false;
  return true;
}

int main() {
  std::cout << std::format("{} {} {} {}\n", is_anagram("listen", "silent"), is_anagram("rat", "car"),
                           is_anagram("", ""), is_anagram("caf\xc3\xa9", "\xc3\xa9" "fac"));
}

