int main() {
  const std::vector<int> v;
  int rises = 0;
  for (std::size_t i = 0; i < v.size() - 1; ++i)  // size() - 1 wraps round when v is empty
    if (v[i + 1] > v[i]) ++rises;
  std::cout << rises << '\n';
}

#include <cstddef>
#include <format>
#include <iostream>
#include <span>
#include <vector>

[[nodiscard]] std::ptrdiff_t rises(std::span<const int> v) {
  std::ptrdiff_t count = 0;
  for (std::ptrdiff_t i = 0; i < std::ssize(v) - 1; ++i)
    if (v[i + 1] > v[i]) ++count;
  return count;
}

int main() {
  const std::vector<int> empty;
  const std::vector<int> one{7};
  const std::vector<int> some{1, 3, 2, 5};
  std::cout << std::format("{} {} {}\n", rises(empty), rises(one), rises(some));
}

